function applyLanguage(){const lang=S.get("language","fr"),english=lang==="en";document.documentElement.lang=lang;document.title=english?"OUSFAL CONNECT - The marketplace for talent and services":"OUSFAL CONNECT \u2014 Le march\u00e9 des talents et services";const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest("script,style,#language-toggle"))continue;if(!textOriginals.has(node))textOriginals.set(node,node.nodeValue);const original=textOriginals.get(node),trimmed=original.trim();node.nodeValue=english?Object.entries(EN).sort((a,b)=>b[0].length-a[0].length).reduce((value,[fr,en])=>value.replaceAll(fr,en),original):original}document.querySelectorAll("[placeholder],[aria-label]").forEach(el=>["placeholder","aria-label"].forEach(key=>{if(!el.hasAttribute(key))return;let values=attrOriginals.get(el);if(!values){values={};attrOriginals.set(el,values)}if(!(key in values))values[key]=el.getAttribute(key);const original=values[key];el.setAttribute(key,english?(EN[original]||original):original)}));const toggle=document.getElementById("language-toggle");if(toggle){toggle.textContent=english?"Fran\u00e7ais":"EN";toggle.setAttribute("aria-label",english?"Switch to French":"Passer en anglais")}}
