const POPULAR_PRODUCT_IDS=[11,12,13,14,20,21,23,25,29,30];
const st=k=>{const data=S.get(k,D[k]);if(k==='requests'||k==='listings')return [...D[k],...data.filter(x=>!D[k].some(seed=>seed.id===x.id))];return data};
let user=S.get('user',null),saved=S.get('saved',[]);
let registerRole=null,registerStep=0;
const $=s=>document.querySelector(s),app=$('#app');
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)};
const card=l=>`<article class="card"><div class="img"><img class="service-photo" data-category="${esc(l.c)}" src="${servicePhoto(l.c,l.t).replaceAll('&','&amp;')}" alt="" loading="lazy"></div><div class="b"><span class="tag">${esc(catN(l.c))}</span><h3><a href="#/l/${l.id}">${esc(l.t)}</a></h3><p class="mu">${esc(l.pv)} · ${esc(l.city)}</p><p class="price">${fcfa(l.p)}</p><button class="btn sm out" data-save="${l.id}" aria-pressed="${saved.includes(l.id)}">${saved.includes(l.id)?"\u{2605} Enregistré":"\u{2606} Enregistrer"}</button></div></article>`;
const catCards=()=>`<div class="cats">${CATS.map(c=>`<a class="cat" href="#/search?cat=${c[0]}"><i>${catI(c[0])}</i>${c[1]}</a>`).join('')}</div>`;
function nav(){const h=location.hash||'#/';const L=[['#/','Accueil'],['#/search','Catalogue'],['#/requests','Demandes'],['#/expo','OUSFAL EXPO']];if(user){L.push(['#/messages','Messages'],['#/saved','Favoris']);if(user.role==='admin')L.push(['#/admin','Admin'])}
 $('#nav').innerHTML=L.map(l=>`<a href="${l[0]}" class="${h===l[0]?'on':''}">${l[1]}</a>`).join('')+(user?`<a href="#/" data-logout>Quitter (${esc(user.name)})</a>`:`<a href="#/login">Connexion</a><a class="gold" href="#/register">S'inscrire</a>`)}
const V={
home:()=>`<section class="hero"><div class="hero-carousel" aria-hidden="true">${HERO_IMAGES.map((src,i)=>`<img class="hero-slide ${i===0?'active':''}" data-category="${CATS[i][0]}" src="${src.replaceAll('&','&amp;')}" alt="">`).join('')}</div><h1>Vous avez des besoins, <em>imaginez</em>, nos créateurs réalisent.</h1><p>La plateforme qui valorise tous les talents camerounais.</p>
<form class="bar" data-search style="grid-template-columns:1fr"><label class="sr" for="q">Votre besoin</label><input id="q" placeholder="Ex : menuisier, robe wax, site web"><button class="btn gold" type="submit" aria-label="Valider la recherche"><svg viewBox="0 0 24 24" aria-hidden="true" width="20" height="20"><circle cx="10.8" cy="10.8" r="6.5" fill="none" stroke="currentColor" stroke-width="2"/><path d="m16 16 5 5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button></form>
<div class="row"><a class="btn" style="background:#fff;color:var(--p);border-color:#fff" href="#/publish">Je recherche une solution</a><a class="btn or" href="#/register">Je suis un créateur de talents</a></div><div class="hero-dots" role="group" aria-label="Choisir l\u2019image de fond">${HERO_IMAGES.map((_,i)=>`<button class="hero-dot ${i===0?'active':''}" type="button" data-slide="${i}" aria-label="Image ${i+1}" aria-pressed="${i===0}"></button>`).join('')}</div></section>
<section class="sec"><h2>Catégories</h2>${catCards()}</section>
<section class="sec"><div class="section-heading"><h2>Services populaires</h2><a href="#/search">Voir le catalogue &rarr;</a></div>${slidingRow(st('listings').slice(0,10),card,'Services populaires')}</section>
<section class="sec"><div class="section-heading"><h2>Produits populaires</h2><a href="#/search">Voir les produits &rarr;</a></div>${slidingRow(st('listings').filter(l=>POPULAR_PRODUCT_IDS.includes(l.id)),card,'Produits populaires')}</section>

<section class="sec"><h2>Demandes récentes</h2><div class="grid">${st('requests').map(r=>reqCard(r)).join('')}</div></section>
<section class="sec"><div class="section-heading"><h2>OUSFAL EXPO <span class="tag ad">Publicit&eacute;</span></h2><a href="#/expo">Voir toutes les offres &rarr;</a></div>${slidingRow(expoRailItems(),adCard,'OUSFAL EXPO')}</section>
<section class="sec"><h2>Comment &ccedil;a marche</h2><div class="how-steps"><div class="card b how-card"><span class="how-number">01</span><h3>Publiez</h3><p>D&eacute;crivez votre besoin.</p></div><div class="card b how-card"><span class="how-number">02</span><h3>D&eacute;couvrez</h3><p>Parcourez les services et les talents.</p></div><div class="card b how-card"><span class="how-number">03</span><h3>Comparez</h3><p>Recevez et comparez les propositions.</p></div><div class="card b how-card"><span class="how-number">04</span><h3>&Eacute;changez</h3><p>Choisissez un cr&eacute;ateur et discutez.</p></div></div></section>
<section class="sec"><div class="section-heading"><h2>Produits et services r\u00e9cents</h2><a href="#/search">Tout le catalogue &rarr;</a></div><div class="grid recent-listings">${st('listings').filter(l=>l.id>=11&&l.id<=30).map(card).join('')}</div></section>
`,
search(q){const p=new URLSearchParams(q);const f={q:p.get('q')||'',cat:p.get('cat')||'',city:p.get('city')||'',s:p.get('s')||'new'};
 let r=st('listings').filter(l=>(!f.cat||l.c===f.cat)&&(!f.city||l.city===f.city)&&(!f.q||(l.t+l.d+l.pv).toLowerCase().includes(f.q.toLowerCase())));
 r.sort((a,b)=>f.s==='asc'?a.p-b.p:f.s==='desc'?b.p-a.p:a.date-b.date);
 return `<h1>Catalogue</h1><form class="bar" data-filter><input name="q" value="${esc(f.q)}" placeholder="Mot-clé" aria-label="Mot-clé"><select name="cat" aria-label="Catégorie"><option value="">Toutes catégories</option>${CATS.map(c=>`<option value="${c[0]}" ${f.cat===c[0]?'selected':''}>${c[1]}</option>`).join('')}</select><select name="city" aria-label="Ville"><option value="">Toutes villes</option>${['Yaoundé','Douala'].map(c=>`<option ${f.city===c?'selected':''}>${c}</option>`).join('')}</select><select name="s" aria-label="Tri"><option value="new">Plus récents</option><option value="asc" ${f.s==='asc'?'selected':''}>Prix croissant</option><option value="desc" ${f.s==='desc'?'selected':''}>Prix décroissant</option></select></form>
 <p class="mu" aria-live="polite">${r.length} résultat(s)</p>${r.length?`<div class="grid">${r.map(card).join('')}</div>`:'<div class="empty"><p>Aucun résultat. Essayez d\'autres mots-clés ou <a href="#/search">réinitialisez les filtres</a>.</p></div>'}`},
l(id){const l=st('listings').find(x=>x.id==id);if(!l)return V.nf();return `<a href="#/search">← Retour</a><div class="card"><div class="img" style="height:200px;font-size:80px" aria-hidden="true">${catI(l.c)}</div><div class="b"><span class="tag">${esc(catN(l.c))}</span><h1>${esc(l.t)}</h1><p class="price">${fcfa(l.p)}</p><p>${esc(l.d)}</p><p class="mu">Prestataire : <a href="#/pv/${encodeURIComponent(l.pv)}">${esc(l.pv)}</a> · ${esc(l.city)}</p><div class="row"><a class="btn" href="#/messages">Démarrer une conversation</a><button class="btn out" data-save="${l.id}">${saved.includes(l.id)?"\u{2605} Enregistré":"\u{2606} Enregistrer"}</button></div></div></div>`},
pv(n){n=decodeURIComponent(n);const ls=st('listings').filter(x=>x.pv===n);if(!ls.length)return V.nf();return `<a href="#/search">&larr; Catalogue</a><div class="card b"><h1>${esc(n)}</h1><p class="mu">${esc(ls[0].city)} &middot; ${[...new Set(ls.map(x=>catN(x.c)))].join(', ')}</p><p>D&eacute;couvrez les offres de ce cr&eacute;ateur et contactez-le pour &eacute;changer sur votre projet.</p><a class="btn" href="#/messages">Contacter</a></div><h2>Services publi&eacute;s</h2><div class="grid">${ls.map(card).join('')}</div>`},
expo(){const ads=st('ads').filter(a=>a.on);return `<h1>OUSFAL EXPO</h1><div class="grid">${ads.length?ads.map(adCard).join(''):''}</div>${ads.length?'':'<div class="empty">Aucune campagne active.</div>'}`},
requests(q){const p=new URLSearchParams(q||''),f={q:p.get('q')||'',cat:p.get('cat')||'',city:p.get('city')||'',min:p.get('min')||'',max:p.get('max')||'',sort:p.get('sort')||'new'};let items=st('requests').filter(r=>(!f.cat||r.c===f.cat)&&(!f.city||r.city===f.city)&&(!f.min||Number(r.b)>=Number(f.min))&&(!f.max||Number(r.b)<=Number(f.max))&&(!f.q||(r.t+' '+r.d+' '+catN(r.c)+' '+r.city).toLocaleLowerCase().includes(f.q.toLocaleLowerCase())));items.sort((a,b)=>f.sort==='low'?a.b-b.b:f.sort==='high'?b.b-a.b:Number(b.id)-Number(a.id));const cities=[...new Set(st('requests').map(r=>r.city))].sort();return `<div class="row request-title"><div><span class="signup-eyebrow">OUSFAL CONNECT</span><h1>Demandes de services</h1><p class="mu">Parcourez les besoins publi&eacute;s et trouvez une mission qui vous correspond.</p></div><a class="btn" href="#/publish">Publier un besoin</a></div><form class="request-filters" data-request-filter><label class="request-keyword">Recherche<input name="q" value="${esc(f.q)}" placeholder="M&eacute;tier, service, mot-cl&eacute;" aria-label="Rechercher une demande"></label><label>Cat&eacute;gorie<select name="cat"><option value="">Toutes les cat&eacute;gories</option>${CATS.map(c=>`<option value="${c[0]}" ${f.cat===c[0]?'selected':''}>${c[1]}</option>`).join('')}</select></label><label>Ville<select name="city"><option value="">Toutes les villes</option>${cities.map(c=>`<option ${f.city===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Budget min. (FCFA)<input name="min" type="number" min="0" value="${esc(f.min)}" placeholder="0"></label><label>Budget max. (FCFA)<input name="max" type="number" min="0" value="${esc(f.max)}" placeholder="Sans limite"></label><label>Trier par<select name="sort"><option value="new" ${f.sort==='new'?'selected':''}>Plus r&eacute;centes</option><option value="low" ${f.sort==='low'?'selected':''}>Budget croissant</option><option value="high" ${f.sort==='high'?'selected':''}>Budget d&eacute;croissant</option></select></label><div class="request-filter-actions"><button class="btn" type="submit">Rechercher</button><a class="btn out" href="#/requests">Effacer les filtres</a></div></form><div class="request-results"><p class="mu" aria-live="polite">${items.length} demande${items.length===1?'':'s'} trouv&eacute;e${items.length===1?'':'s'}</p>${items.length?`<div class="grid">${items.map(reqCard).join('')}</div>`:'<div class="empty">Aucune demande ne correspond &agrave; ces filtres. Essayez d&rsquo;&eacute;largir votre recherche.</div>'}</div>`},
r(id){const r=st('requests').find(x=>x.id==id);if(!r)return V.nf();const ps=st('proposals').filter(p=>p.rid==id);
 return `<a href="#/requests">← Retour</a><h1>${esc(r.t)}</h1><p>${esc(r.d)}</p><p class="mu">${esc(r.city)} · Budget ${fcfa(r.b)} · avant le ${esc(r.dl)}</p><h2>Propositions (${ps.length})</h2>
 ${ps.length?`<div class="tw"><table><tr><th>Prestataire</th><th>Prix</th><th>Délai</th><th>Statut</th><th></th></tr>${ps.map(p=>`<tr><td>${esc(p.pv)}<br><span class="mu">${esc(p.msg)}</span></td><td>${fcfa(p.price)}</td><td>${p.days} j</td><td><span class="tag ${p.st==='retenue'?'ok':''}">${p.st}</span></td><td>${p.st==='en attente'?`<button class="btn sm" data-pick="${p.id}">Choisir</button>`:''}</td></tr>`).join('')}</table></div>`:'<div class="empty">Aucune proposition.</div>'}
 <h2>Soumettre une proposition</h2><form class="f" data-prop="${r.id}" novalidate><label for="pp">Prix (FCFA)</label><input id="pp" name="price" type="number" min="1"><div class="err"></div><label for="pd">Délai (jours)</label><input id="pd" name="days" type="number" min="1"><div class="err"></div><label for="pm">Message</label><textarea name="msg" id="pm"></textarea><button class="btn">Envoyer</button></form>`},
publish(){return `<h1>Publier un besoin</h1><form class="f" data-pub novalidate><label for="t">Titre</label><input id="t" name="t"><div class="err"></div><label for="c">Catégorie</label><select id="c" name="c"><option value="">Choisir…</option>${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select><div class="err"></div><label for="d">Description</label><textarea id="d" name="d"></textarea><div class="err"></div><label for="ci">Ville</label><select id="ci" name="city"><option>Yaoundé</option><option>Douala</option></select><label for="b">Budget indicatif (FCFA)</label><input id="b" name="b" type="number" min="0"><div class="err"></div><label for="dl">Date limite</label><input id="dl" name="dl" type="date"><div class="err"></div><label for="im">Images (optionnel)</label><input id="im" type="file" accept="image/*" multiple data-img><div class="prev" id="prev"></div><br><button class="btn">Publier</button></form>`},
messages(id){const cs=st('convos');const c=cs.find(x=>x.id==id)||cs[0];return `<h1>Messages</h1><div class="chat"><div>${cs.map(x=>`<a class="cv ${x.id===c.id?'on':''}" href="#/messages/${x.id}"><strong>${esc(x.w)}</strong><br><span class="mu">${esc(x.m[x.m.length-1].x)}</span></a>`).join('')}</div><div><div class="msgs" id="msgs">${c.m.map(m=>`<div class="m ${m.me?'me':''}">${esc(m.x)}<small>${esc(m.t)}</small></div>`).join('')}</div><form class="row" data-msg="${c.id}" style="margin-top:8px"><input name="x" aria-label="Message" placeholder="Votre message" style="flex:1" required><button class="btn">Envoyer</button></form></div></div>`},
saved(){const l=st('listings').filter(x=>saved.includes(x.id));return `<h1>Favoris</h1>${l.length?`<div class="grid">${l.map(card).join('')}</div>`:'<div class="empty">Aucun favori pour l\'instant.</div>'}`},
login(){return `<section class="signin-panel"><h1>Connexion</h1><form class="f" data-login novalidate><label for="e">E-mail</label><input id="e" name="e" type="email" autocomplete="email"><div class="err"></div><label for="pw">Mot de passe</label><input id="pw" name="pw" type="password" autocomplete="current-password"><div class="err"></div><button class="btn" type="submit" disabled aria-disabled="true">Connexion indisponible</button></form><p class="mu">La connexion sera disponible prochainement.</p><p class="signin-signup">Vous n&rsquo;avez pas encore de compte ? <a href="#/register">Cr&eacute;er un compte</a></p></section>`},
register(){
 if(!registerRole)return `<section class="signup-wrap"><a class="signup-back" href="#/">&larr; Retour &agrave; l&rsquo;accueil</a><div class="signup-heading"><span class="signup-eyebrow">OUSFAL CONNECT &middot; INSCRIPTION</span><h1>Comment souhaitez-vous utiliser la plateforme ?</h1><p>Choisissez votre espace. Nous adapterons l&rsquo;inscription &agrave; votre activit&eacute;.</p></div><div class="signup-choices"><button class="signup-choice" type="button" data-role-choice="customer"><span class="signup-choice-icon" aria-hidden="true">&#128269;</span><span class="signup-choice-copy"><strong>Je cherche une solution</strong><small>D&eacute;crivez vos besoins et trouvez le bon talent au Cameroun.</small><b>Cr&eacute;er un compte client <span>&rarr;</span></b></span></button><button class="signup-choice creator" type="button" data-role-choice="provider"><span class="signup-choice-icon" aria-hidden="true">&#10022;</span><span class="signup-choice-copy"><strong>Je propose mes services</strong><small>Pr&eacute;sentez votre savoir-faire, vos cr&eacute;ations ou vos produits.</small><b>Cr&eacute;er un compte cr&eacute;ateur <span>&rarr;</span></b></span></button></div><p class="signup-footnote">Vous avez d&eacute;j&agrave; un compte ? <a href="#/login">Se connecter</a></p></section>`;
 const provider=registerRole==='provider', steps=provider?['Votre compte','Votre activit&eacute;','Votre profil']:['Votre compte','Votre besoin','Vos pr&eacute;f&eacute;rences'];
 const cities=['Yaound&eacute;','Douala','Bafoussam','Bamenda','Garoua','Maroua','Kribi','Autre'];
 const fields=provider?[
 `<div class="signup-fields"><label>Nom complet<input name="name" autocomplete="name" required placeholder="Ex. Amina Mvondo"></label><label>Adresse e-mail<input name="email" type="email" autocomplete="email" required placeholder="vous@exemple.com"></label><label>T&eacute;l&eacute;phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" required placeholder="+237 6XX XXX XXX"></label><label>Mot de passe<input name="password" type="password" minlength="6" autocomplete="new-password" required placeholder="6 caract&egrave;res minimum"></label></div>`,
 `<div class="signup-fields"><label>Nom de votre activit&eacute;<input name="business" required placeholder="Nom commercial ou votre nom"></label><label>Domaines de comp&eacute;tence<select name="category" required><option value="">Choisir un domaine</option>${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></label><label>Ann&eacute;es d&rsquo;exp&eacute;rience<select name="experience" required><option value="">S&eacute;lectionner</option><option>D&eacute;butant</option><option>1 &agrave; 3 ans</option><option>4 &agrave; 7 ans</option><option>8 ans et plus</option></select></label><label>&Agrave; propos de votre activit&eacute;<textarea name="about" required placeholder="Pr&eacute;sentez vos services, votre exp&eacute;rience et ce qui vous distingue."></textarea></label></div>`,
 `<div class="signup-fields"><label>Ville<select name="city" required><option value="">Choisir une ville</option>${cities.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Quartier<input name="district" required placeholder="Ex. Bastos, Akwa, Bonamoussadi"></label><label>Portfolio ou r&eacute;seaux <span>(facultatif)</span><input name="portfolio" type="url" placeholder="https://"></label><label class="signup-check"><input type="checkbox" name="terms" required> J&rsquo;accepte les conditions d&rsquo;utilisation et la politique de confidentialit&eacute;.</label></div>`
 ]:[
 `<div class="signup-fields"><label>Nom complet<input name="name" autocomplete="name" required placeholder="Ex. Alain Tchoumi"></label><label>Adresse e-mail<input name="email" type="email" autocomplete="email" required placeholder="vous@exemple.com"></label><label>T&eacute;l&eacute;phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" required placeholder="+237 6XX XXX XXX"></label><label>Mot de passe<input name="password" type="password" minlength="6" autocomplete="new-password" required placeholder="6 caract&egrave;res minimum"></label></div>`,
 `<div class="signup-fields"><label>Que recherchez-vous ?<select name="category" required><option value="">Choisir un domaine</option>${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select></label><label>D&eacute;crivez votre besoin<textarea name="need" required placeholder="Expliquez ce que vous souhaitez r&eacute;aliser ou trouver."></textarea></label><label>Budget indicatif <span>(facultatif)</span><select name="budget"><option value="">Je pr&eacute;f&egrave;re en discuter</option><option>Moins de 25 000 FCFA</option><option>25 000 &ndash; 100 000 FCFA</option><option>100 000 &ndash; 500 000 FCFA</option><option>Plus de 500 000 FCFA</option></select></label></div>`,
 `<div class="signup-fields"><label>Ville<select name="city" required><option value="">Choisir une ville</option>${cities.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Quartier <span>(facultatif)</span><input name="district" placeholder="Ex. Bastos, Akwa, Bonamoussadi"></label><label class="signup-check"><input type="checkbox" name="terms" required> J&rsquo;accepte les conditions d&rsquo;utilisation et la politique de confidentialit&eacute;.</label></div>`
 ];
 return `<section class="signup-wrap"><button class="signup-back" type="button" data-role-back>&larr; Changer de profil</button><div class="signup-heading"><span class="signup-eyebrow">INSCRIPTION &middot; ${provider?'ESPACE CR&Eacute;ATEUR':'ESPACE CLIENT'}</span><h1>${provider?'Rejoignez les cr&eacute;ateurs OUSFAL':'Trouvez la bonne solution'}</h1><p>Quelques &eacute;tapes pour cr&eacute;er votre espace ${provider?'cr&eacute;ateur':'client'}.</p></div><div class="signup-progress" aria-label="&Eacute;tapes d&rsquo;inscription">${steps.map((x,i)=>`<div class="signup-progress-step ${i<=registerStep?'active':''}"><span>${i+1}</span><small>${x}</small></div>`).join('')}</div><form class="signup-form" data-register novalidate>${fields.map((html,i)=>`<fieldset class="signup-panel" data-signup-step="${i}" ${i===registerStep?'':'hidden'}><legend>${steps[i]}</legend>${html}<div class="signup-error" aria-live="polite"></div><div class="signup-actions">${i>0?'<button class="btn out" type="button" data-step-back>Pr&eacute;c&eacute;dent</button>':'<span></span>'}${i<2?'<button class="btn" type="button" data-step-next>Continuer <span>&rarr;</span></button>':'<button class="btn" type="submit">Cr&eacute;er mon compte</button>'}</div></fieldset>`).join('')}</form><p class="signup-footnote">D?j? inscrit ? <a href="#/login">Se connecter</a></p></section>`
 },
admin(){if(!user||user.role!=='admin')return '<div class="empty">Accès réservé aux administrateurs (démo : connectez-vous avec le rôle Administrateur).</div>';const ads=st('ads');
 return `<h1>Admin — OUSFAL EXPO</h1><div class="grid"><div class="card b"><h3>${st('listings').length}</h3>annonces</div><div class="card b"><h3>${st('requests').length}</h3>demandes</div><div class="card b"><h3>${ads.filter(a=>a.on).length}/${ads.length}</h3>campagnes actives</div></div>
 <h2>Nouvelle publicité</h2><form class="f" data-ad novalidate><label for="at">Titre</label><input id="at" name="t"><div class="err"></div><label for="ap">Partenaire</label><input id="ap" name="pt"><div class="err"></div><label for="ac">Catégorie</label><select id="ac" name="c">${CATS.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select><br><br><button class="btn">Créer (inactive)</button></form>
 <h2>Campagnes</h2><div class="tw"><table>${ads.map(a=>`<tr><td>${esc(a.t)}<br><span class="mu">${esc(a.pt)}</span></td><td><span class="tag ${a.on?'ok':''}">${a.on?'Active':'Inactive'}</span></td><td><button class="btn sm out" data-tog="${a.id}">${a.on?'Désactiver':'Publier'}</button> <button class="btn sm dng" data-del="${a.id}">Supprimer</button></td></tr>`).join('')}</table></div>`},
help(){return `<section class="help-page"><span class="signup-eyebrow">OUSFAL CONNECT</span><h1>Aide et contact</h1><p>Notre &eacute;quipe est &agrave; votre &eacute;coute pour vous accompagner dans l&rsquo;utilisation de la plateforme.</p><div class="help-contact"><a class="btn" href="tel:+237672211172">Appeler le 672 211 172</a><a class="btn out" href="https://wa.me/237672211172">Nous &eacute;crire sur WhatsApp</a></div><h2>Besoin d&rsquo;aide avec une annonce ?</h2><p>Indiquez le lien de l?annonce concern&eacute;e lorsque vous contactez notre &eacute;quipe.</p></section>`},
nf(){return '<div class="empty">Page introuvable. <a href="#/">Accueil</a></div>'}};
const reqCard=r=>`<article class="card"><div class="b"><span class="tag">${esc(catN(r.c))}</span><h3><a href="#/r/${r.id}">${esc(r.t)}</a></h3><p class="mu">${esc(r.city)} · Budget ${fcfa(r.b)}</p></div></article>`;
const adCard=a=>`<article class="card"><div class="img"><img class="service-photo" data-category="${esc(a.c)}" src="${servicePhoto(a.c,a.t).replaceAll('&','&amp;')}" alt="" loading="lazy"></div><div class="b"><span class="tag ad">Offre partenaire</span><h3>${esc(a.t)}</h3><p class="mu">${esc(a.pt)}</p><a class="btn sm" href="#/search?cat=${a.c}">Découvrir</a></div></article>`;
let heroCarouselTimer;function initHeroCarousel(){clearInterval(heroCarouselTimer);const hero=document.querySelector(".hero");if(!hero)return;const slides=[...hero.querySelectorAll(".hero-slide")],dots=[...hero.querySelectorAll(".hero-dot")];let current=0;const show=i=>{current=(i+slides.length)%slides.length;slides.forEach((el,n)=>el.classList.toggle("active",n===current));dots.forEach((el,n)=>{el.classList.toggle("active",n===current);el.setAttribute("aria-pressed",String(n===current))})};dots.forEach(dot=>dot.addEventListener("click",()=>show(Number(dot.dataset.slide))));if(!matchMedia("(prefers-reduced-motion: reduce)").matches)heroCarouselTimer=setInterval(()=>show(current+1),6500)}
function expoRailItems(){const active=st('ads').filter(a=>a.on);const seeds=D.ads.filter(a=>a.on&&!active.some(x=>x.id===a.id));return [...active,...seeds].slice(0,10)}
function slidingRow(items,renderCard,label){const cards=items.map(renderCard).join('');return `<div class="auto-slider-shell"><button class="rail-arrow rail-prev" type="button" aria-label="Previous" data-rail="prev">&#8249;</button><div class="auto-slider" role="region" aria-label="${label}"><div class="auto-slider-track"><div class="auto-slider-group">${cards}</div><div class="auto-slider-group" aria-hidden="true" inert>${cards}</div></div></div><button class="rail-arrow rail-next" type="button" aria-label="Next" data-rail="next">&#8250;</button></div>`}
function render(){const h=(location.hash||'#/').slice(1);const [path,q]=h.split('?');const [,a,b]=path.split('/');
 const guard=['messages','saved'].includes(a)&&!user;
 let html=guard?'<div class="empty">Connectez-vous pour accéder à cette page. <a href="#/login">Connexion</a></div>':
 ({'':()=>V.home(),search:()=>V.search(q),l:()=>V.l(b),pv:()=>V.pv(b),expo:V.expo,requests:()=>V.requests(q),r:()=>V.r(b),publish:V.publish,messages:()=>V.messages(b),saved:V.saved,login:V.login,register:V.register,admin:V.admin,help:V.help}[a||'']||V.nf)();
 app.innerHTML=html;if((location.hash||"#/")==="#/"){initHeroCarousel();document.querySelectorAll("#app .sec").forEach((el,i)=>{el.classList.add("reveal");el.style.transitionDelay=(Math.min(i,4)*70)+"ms"});if("IntersectionObserver" in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("in-view");observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll("#app .reveal").forEach(el=>observer.observe(el))}else document.querySelectorAll("#app .reveal").forEach(el=>el.classList.add("in-view"))}nav();applyLanguage();$('#nav').classList.remove('open');$('#burger').setAttribute('aria-expanded','false');window.scrollTo(0,0)}
const setErr=(el,m)=>{el.closest('form').querySelectorAll('.err').length;const e=el.nextElementSibling;if(e&&e.classList.contains('err'))e.textContent=m||''};
const need=(f,names)=>{let ok=true;names.forEach(n=>{const el=f.elements[n];const bad=!el.value.trim();setErr(el,bad?'Champ requis.':'');if(bad)ok=false});return ok};
document.addEventListener('error',e=>{const img=e.target;if(!(img instanceof HTMLImageElement)||img.dataset.fallback)return;img.dataset.fallback='true';img.src=fallbackImage(img.dataset.category||'batiment')},true);
function showSignupStep(step){registerStep=step;document.querySelectorAll('[data-signup-step]').forEach((panel,i)=>panel.hidden=i!==step);document.querySelectorAll('.signup-progress-step').forEach((item,i)=>item.classList.toggle('active',i<=step));document.querySelector('.signup-heading')?.scrollIntoView({behavior:'smooth',block:'start'})}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;
 if(t.dataset.roleChoice){registerRole=t.dataset.roleChoice;registerStep=0;render();return}
 if(t.hasAttribute('data-role-back')){registerRole=null;registerStep=0;render();return}
 if(t.hasAttribute('data-step-next')){const panel=t.closest('.signup-panel'),required=[...panel.querySelectorAll('[required]')];let ok=true;for(const input of required){const valid=input.type==='checkbox'?input.checked:input.checkValidity();input.classList.toggle('invalid',!valid);if(!valid)ok=false}const error=panel.querySelector('.signup-error');if(error)error.textContent=ok?'':'Veuillez compl?ter les champs obligatoires.';if(ok)showSignupStep(Math.min(registerStep+1,2));return}
 if(t.hasAttribute('data-step-back')){showSignupStep(Math.max(registerStep-1,0));return}

 if(t.dataset.rail){const track=t.closest('.auto-slider-shell')?.querySelector('.auto-slider-track');const animation=track?.getAnimations()[0];if(animation){const group=track.querySelector('.auto-slider-group');const step=260+(parseFloat(getComputedStyle(group).gap)||14);const duration=Number(animation.effect.getTiming().duration)||54000;animation.currentTime=(Number(animation.currentTime)||0)+(t.dataset.rail==='next'?-1:1)*duration*step/(group.scrollWidth+14)}return}
 if(t.id==='language-toggle'){S.set('language',S.get('language','fr')==='fr'?'en':'fr');render();return}
 if(t.id==='burger'){const o=$('#nav').classList.toggle('open');t.setAttribute('aria-expanded',o)}
 if(t.dataset.save){const id=+t.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];S.set('saved',saved);toast('Favoris mis à jour');render()}
 if(t.dataset.pick){const ps=st('proposals').map(p=>({...p,st:p.id==t.dataset.pick?'retenue':(p.rid===st('proposals').find(x=>x.id==t.dataset.pick).rid?'refusée':p.st)}));S.set('proposals',ps);toast('Prestataire sélectionné');render()}
 if(t.dataset.tog){S.set('ads',st('ads').map(a=>a.id==t.dataset.tog?{...a,on:!a.on}:a));render()}
 if(t.dataset.del&&confirm('Supprimer définitivement cette publicité ?')){S.set('ads',st('ads').filter(a=>a.id!=t.dataset.del));toast('Publicité supprimée');render()}
 if(t.hasAttribute('data-logout')){user=null;S.set('user',null);toast('Déconnecté')}});
document.addEventListener('change',e=>{const f=e.target.closest('[data-filter]');if(f){const p=new URLSearchParams(new FormData(f));location.hash='#/search?'+p}
 if(e.target.dataset.img){const pv=$('#prev');pv.innerHTML='';[...e.target.files].slice(0,5).forEach(file=>{if(!file.type.startsWith('image/'))return;const i=new Image();i.alt='Aperçu';i.src=URL.createObjectURL(file);pv.appendChild(i)})}});
document.addEventListener('submit',e=>{const f=e.target;e.preventDefault();
 if(f.matches('[data-search]'))location.hash='#/search?q='+encodeURIComponent(f.q.value);
 if(f.matches('[data-filter]'))location.hash='#/search?'+new URLSearchParams(new FormData(f));
 if(f.matches('[data-request-filter]'))location.hash='#/requests?'+new URLSearchParams(new FormData(f));
 if(f.matches('[data-register]')){const panel=f.querySelector(`[data-signup-step="${registerStep}"]`),required=[...panel.querySelectorAll('[required]')];let ok=true;for(const input of required){const valid=input.type==='checkbox'?input.checked:input.checkValidity();input.classList.toggle('invalid',!valid);if(!valid)ok=false}if(!ok){panel.querySelector('.signup-error').textContent='V?rifiez les champs obligatoires avant de continuer.';return}const values=Object.fromEntries(new FormData(f).entries());const {name,email,password,...profile}=values;user={name:name.trim(),role:registerRole};S.set('user',user);S.set('profile',{...profile,role:registerRole,name:name.trim(),email:email.trim(),createdAt:new Date().toISOString()});registerRole=null;registerStep=0;toast('Bienvenue sur OUSFAL CONNECT !');location.hash='#/';return}

 if(f.matches('[data-pub]')){let ok=need(f,['t','c','d','b','dl']);if(ok){const r=st('requests');S.set('requests',[{id:Date.now(),t:f.t.value.trim(),c:f.c.value,city:f.city.value,b:+f.b.value,dl:f.dl.value,d:f.d.value.trim(),by:user?user.name:'Invité'},...r]);toast('Demande publiée');location.hash='#/requests'}}
 if(f.matches('[data-prop]')){let ok=need(f,['price','days']);if(ok){S.set('proposals',[...st('proposals'),{id:Date.now(),rid:+f.dataset.prop,pv:user?user.name:'Prestataire OUSFAL',price:+f.price.value,days:+f.days.value,msg:f.msg.value.trim(),st:'en attente'}]);toast('Proposition envoyée');render()}}
 if(f.matches('[data-ad]')){if(need(f,['t','pt'])){S.set('ads',[...st('ads'),{id:Date.now(),t:f.t.value.trim(),pt:f.pt.value.trim(),c:f.c.value,on:false}]);toast('Publicité créée');render()}}
 if(f.matches('[data-msg]')){const x=f.x.value.trim();if(!x)return;const id=+f.dataset.msg,now=new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});S.set('convos',st('convos').map(c=>c.id===id?{...c,m:[...c.m,{me:1,x,t:now}]}:c));render()}});
window.addEventListener('hashchange',render);render();
